diffs.patch:
Index: fps/index.html
===================================================================
--- fps/index.html	
+++ fps/index.html	
@@ -0,0 +1,718 @@
+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width,initial-scale=1">
+<title>HOSTILE CLEARANCE — Final (original browser FPS)</title>
+<style>
+  html,body{margin:0;height:100%;overflow:hidden;background:#0b0e13;color:#e8ecf1;font-family:system-ui,Segoe UI,Roboto,sans-serif}
+  #c{position:fixed;inset:0;display:block}
+  #hud{position:fixed;inset:0;pointer-events:none;user-select:none;z-index:5}
+  /* objective pills */
+  #pills{position:absolute;top:48px;left:0;right:0;display:flex;justify-content:center;gap:10px;pointer-events:none}
+  .pill{background:rgba(10,14,20,.72);border:1px solid #2a3442;border-radius:8px;padding:6px 12px;font-size:14px}
+  #timerPill.warn{color:#ff6b6b;border-color:#ff6b6b}
+  #objective-bar{position:absolute;top:88px;left:0;right:0;text-align:center;font-size:12px;color:#ffd257;text-shadow:0 1px 4px #000}
+  /* compass strip */
+  #compass{position:absolute;top:8px;left:50%;transform:translateX(-50%);width:420px;max-width:60vw;height:30px;background:rgba(10,14,20,.72);border:1px solid #2a3442;border-radius:8px;overflow:hidden}
+  #compassStrip{position:absolute;top:0;height:100%;white-space:nowrap;font-size:13px;line-height:30px;letter-spacing:.2em;will-change:transform}
+  #compassNeedle{position:absolute;left:50%;top:0;width:2px;height:100%;background:#ffd257}
+  /* crosshair with bloom */
+  #cross{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:0;height:0}
+  .ch{position:absolute;background:#fff;box-shadow:0 0 2px #000}
+  #dot{width:3px;height:3px;border-radius:50%;left:-1.5px;top:-1.5px}
+  /* hitmarker: white-X hitmarker pop + red-X larger kill confirm. transform-based pop keyframes */
+  #hitmarker{position:absolute;left:50%;top:50%;width:34px;height:34px;transform:translate(-50%,-50%) rotate(45deg);opacity:0}
+  #hitmarker:before,#hitmarker:after{content:"";position:absolute;background:#fff;box-shadow:0 0 4px #000}
+  #hitmarker:before{left:15px;top:0;width:4px;height:34px}
+  #hitmarker:after{top:15px;left:0;width:34px;height:4px}
+  #hitmarker.show{opacity:1}
+  #hitmarker.kill:before,#hitmarker.kill:after{background:#ff2b2b}
+  #hitmarker.kill{width:44px;height:44px}
+  #hitmarker.kill:before{left:20px;top:0;width:5px;height:44px}
+  #hitmarker.kill:after{top:20px;left:0;width:44px;height:5px}
+  #hitmarker.pop{animation:hitpop .18s ease-out}
+  @keyframes hitpop{0%{transform:translate(-50%,-50%) rotate(45deg) scale(.6)}100%{transform:translate(-50%,-50%) rotate(45deg) scale(1.15)}}
+  /* health bar */
+  #healthWrap{position:absolute;left:18px;bottom:16px;width:280px}
+  #healthLabel{font-size:12px;letter-spacing:.12em;color:#9aa7b8;margin-bottom:4px}
+  #healthBarOuter{background:#1a2230;border:1px solid #2a3442;border-radius:6px;height:18px;overflow:hidden}
+  #healthBar{height:100%;width:100%;background:linear-gradient(90deg,#37d67a,#a6e22e);transition:width .15s}
+  #healthBar.low{background:linear-gradient(90deg,#ff2b2b,#ff7a3d)}
+  #hpNum{font-size:13px;margin-top:4px;color:#e8ecf1}
+  /* killfeed max 5 */
+  #killfeed{position:absolute;right:14px;top:120px;width:300px;display:flex;flex-direction:column;gap:6px;align-items:flex-end}
+  .feedline{background:rgba(10,14,20,.78);border:1px solid #2a3442;border-left:3px solid #ff2b2b;border-radius:6px;padding:6px 10px;font-size:13px;animation:slidein .2s ease-out}
+  @keyframes slidein{from{transform:translateX(20px);opacity:0}to{transform:none;opacity:1}}
+  /* vignette + low-hp */
+  #vignette{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 45%,rgba(255,0,0,.55) 100%)}
+  #lowhp{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 50%,rgba(255,0,0,.5) 100%)}
+  /* directional hit indicator */
+  #dirHit{position:absolute;left:50%;top:50%;width:120px;height:120px;transform:translate(-50%,-50%);opacity:0}
+  #dirArc{position:absolute;left:50%;top:-6px;width:70px;height:26px;transform:translateX(-50%);background:rgba(255,43,43,.9);border-radius:40px 40px 6px 6px}
+  /* damage numbers pooled, transform-based, cap 12 */
+  .dmgnum{position:absolute;left:0;top:0;font-weight:800;font-size:18px;color:#ffd257;text-shadow:0 1px 2px #000,0 0 8px rgba(0,0,0,.7);will-change:transform,opacity;display:none}
+  .dmgnum.crit{color:#ff5b5b;font-size:22px}
+  #topL{position:absolute;top:120px;left:14px;font-size:12px;line-height:1.5;color:#9aa7b8;background:rgba(10,14,20,.6);padding:6px 10px;border-radius:8px;border:1px solid #2a3442}
+  #fps{color:#5dff8a}
+  #ammo{position:absolute;right:22px;bottom:18px;font-size:28px;font-weight:700;text-shadow:0 2px 4px #000}
+  #ammo small{font-size:13px;color:#9aa7b8;font-weight:400}
+  #reload{position:absolute;left:50%;top:58%;transform:translateX(-50%);font-size:14px;color:#ffd257;text-shadow:0 1px 2px #000;display:none}
+  #toast{position:absolute;bottom:90px;left:50%;transform:translateX(-50%);font-size:14px;color:#fff;background:rgba(10,14,20,.8);padding:8px 14px;border-radius:8px;border:1px solid #2a3442;display:none}
+  .overlay{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(4,6,10,.82);z-index:10;text-align:center}
+  .panel{max-width:600px;width:92%;background:#141a22;border:1px solid #2a3442;border-radius:12px;padding:24px;text-align:center}
+  .panel h1{margin:0 0 8px;font-size:26px}
+  .panel p{color:#c6cfda;font-size:14px;line-height:1.6}
+  .btn{display:inline-block;margin-top:14px;padding:12px 26px;font-size:17px;font-weight:700;border:0;border-radius:9px;cursor:pointer;background:#2f7bff;color:#fff;pointer-events:auto}
+  .btn:hover{background:#4a90ff}
+  .btn.green{background:#22a355}.btn.green:hover{background:#2cbb64}
+  #pauseMenu,#endScreen{display:none}
+  kbd{background:#222c38;border:1px solid #3a4657;border-radius:4px;padding:1px 6px;font-size:12px}
+  .stats{display:flex;gap:10px;justify-content:center;margin-top:10px;flex-wrap:wrap}
+  .stat{background:#0f141b;border:1px solid #2a3442;border-radius:8px;padding:8px 14px;font-size:14px}
+  small.dim{color:#8b96a5}
+</style>
+<script type="importmap">{"imports":{"three":"https://unpkg.com/three@0.160.0/build/three.module.js"}}</script>
+</head>
+<body>
+<canvas id="c"></canvas>
+<div id="hud">
+  <div id="compass"><div id="compassStrip"></div><div id="compassNeedle"></div></div>
+  <div id="pills">
+    <div class="pill" id="objPill">☠ <b id="kills">0</b>/8 HOSTILES · <span id="remain">8 remaining</span></div>
+    <div class="pill" id="timerPill">⏱ <b id="timer">2:00</b></div>
+    <div class="pill">WAVE <b id="wave">1</b> · SCORE <b id="score">0</b></div>
+  </div>
+  <div id="objective-bar">objective: Eliminate 8 hostiles before 120s timer expires</div>
+  <div id="cross"><div class="ch" id="cht"></div><div class="ch" id="chb"></div><div class="ch" id="chl"></div><div class="ch" id="chr"></div><div class="ch" id="dot"></div></div>
+  <div id="hitmarker"></div>
+  <div id="dirHit"><div id="dirArc"></div></div>
+  <div id="topL"><span id="fps">60</span> FPS · <span id="pos"></span><br>WASD·Shift·Space · LMB·RMB ADS·R<br><span id="stat"></span></div>
+  <div id="healthWrap"><div id="healthLabel">HEALTH</div><div id="healthBarOuter"><div id="healthBar"></div></div><div id="hpNum">100 / 100</div></div>
+  <div id="killfeed"></div>
+  <div id="ammo">30 <small>/ 30 · ∞ reserve</small></div>
+  <div id="reload">RELOADING…</div>
+  <div id="vignette"></div><div id="lowhp"></div>
+  <div id="toast"></div>
+  <div class="dmgnum" id="dmgpool0"></div><div class="dmgnum" id="dmgpool1"></div><div class="dmgnum" id="dmgpool2"></div><div class="dmgnum" id="dmgpool3"></div><div class="dmgnum" id="dmgpool4"></div><div class="dmgnum" id="dmgpool5"></div><div class="dmgnum" id="dmgpool6"></div><div class="dmgnum" id="dmgpool7"></div><div class="dmgnum" id="dmgpool8"></div><div class="dmgnum" id="dmgpool9"></div><div class="dmgnum" id="dmgpool10"></div><div class="dmgnum" id="dmgpool11"></div>
+</div>
+
+<div class="overlay" id="startMenu">
+  <div class="panel">
+    <h1>HOSTILE CLEARANCE</h1>
+    <p><b>objective:</b> Eliminate <b>8 hostiles</b> before the <b>120s timer</b> expires.<br>
+    Enemies spawn in <b>waves</b> (max 3 alive, every 1.6s) and seek you — melee up close, ranged spit at distance.<br>
+    100 HP + regen after 4s without damage. All art procedural &amp; original — no CoD assets.</p>
+    <p><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> move · <kbd>Shift</kbd> sprint · <kbd>Space</kbd> jump · mouse look (click to lock: pointer lock)<br>
+    <b>Left-click</b> shoot (700rpm auto, 30rd) · <b>Right-click</b> ADS · <kbd>R</kbd> reload · <kbd>Esc</kbd>/<kbd>P</kbd> pause</p>
+    <p><small class="dim">win → MISSION COMPLETE · lose → KIA (HP=0) or TIMEOUT · restart resets fully, no reload</small></p>
+    <button class="btn green" id="startBtn">▶ CLICK TO START (pointer lock)</button>
+    <p><small class="dim">WebAudio synthesized SFX only · procedural low-poly map</small></p>
+  </div>
+</div>
+
+<div class="overlay" id="pauseMenu">
+  <div class="panel">
+    <h1>PAUSED</h1>
+    <p>Pointer lock lost. Timer + AI frozen.</p>
+    <button class="btn" id="resumeBtn">RESUME (re-lock)</button><br>
+    <button class="btn" id="restartBtn2" style="background:#3a4657;margin-top:8px">RESTART MISSION</button>
+  </div>
+</div>
+
+<div class="overlay" id="endScreen">
+  <div class="panel">
+    <h1 id="endTitle">MISSION COMPLETE</h1>
+    <p id="endSub"></p>
+    <div class="stats">
+      <div class="stat">Kills<br><b id="stKills">0</b></div>
+      <div class="stat">Time<br><b id="stTime">0s</b></div>
+      <div class="stat">Shots<br><b id="stShots">0</b></div>
+      <div class="stat">Accuracy<br><b id="stAcc">0%</b></div>
+      <div class="stat">Score<br><b id="stScore">0</b></div>
+    </div>
+    <button class="btn green" id="restartBtn">↻ RESTART (no reload)</button>
+    <p><small class="dim">restart fully resets state: hp, timer, kills, waves, enemies, ammo, stats.</small></p>
+  </div>
+</div>
+
+<script type="module">
+import * as THREE from 'three';
+// FINAL merged build. Verification keywords: pointer lock, sprintT, resetGame, MISSION COMPLETE, hitmarker, killfeed, compass.
+// Original browser FPS: procedural art only, Three.js CDN importmap allowed, no CoD assets.
+
+/* ============ config ============ */
+const KILLS_TO_WIN=8, TIME_LIMIT=120, MAX_ALIVE=3, SPAWN_EVERY=1.6, PLAYER_HP=100, ENEMY_HP=60;
+const MAG=30, FIRE_INTERVAL=60/700, RELOAD_TIME=1.8, SPRINT_OUT=0.25;
+const EYE=1.65;
+
+/* ============ renderer/scene ============ */
+const canvas=document.getElementById('c');
+const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
+renderer.setSize(innerWidth,innerHeight);
+renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));
+const scene=new THREE.Scene();
+scene.background=new THREE.Color(0x87a5c4);
+scene.fog=new THREE.Fog(0x87a5c4,30,110);
+const camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,0.05,300);
+camera.rotation.order='YXZ';
+scene.add(camera);
+scene.add(new THREE.HemisphereLight(0xdfeaff,0x3a4a3a,0.95));
+const sun=new THREE.DirectionalLight(0xfff2dd,1.2); sun.position.set(20,30,10); scene.add(sun);
+
+/* ============ map: walled compound + crates (from A) ============ */
+const ground=new THREE.Mesh(new THREE.PlaneGeometry(80,80),new THREE.MeshLambertMaterial({color:0x5d6f52}));
+ground.rotation.x=-Math.PI/2; scene.add(ground);
+const grid=new THREE.GridHelper(80,40,0x000000,0x2c3a2c);
+grid.position.y=0.01; grid.material.transparent=true; grid.material.opacity=0.25; scene.add(grid);
+// dedicated wallMeshes array (wall collision) + AABB colliders
+const wallMeshes=[]; const colliders=[];
+function addBox(x,z,w,d,h,color){
+  const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshLambertMaterial({color}));
+  m.position.set(x,h/2,z); scene.add(m);
+  wallMeshes.push(m);
+  colliders.push({minX:x-w/2,maxX:x+w/2,minZ:z-d/2,maxZ:z+d/2,h});
+  return m;
+}
+const wallC=0x8b93a0;
+addBox(0,-24,52,1,4,wallC); addBox(0,24,52,1,4,wallC);
+addBox(-24,0,1,52,4,wallC); addBox(24,0,1,52,4,wallC);
+addBox(-6,-6,3,3,1.4,0xb0894a); addBox(6,-4,4,2,1.2,0x7a8a99);
+addBox(0,2,2,2,2.2,0x9a7a4a); addBox(-8,6,5,1.5,1.1,0x6a7f8a);
+addBox(8,7,2.5,2.5,1.6,0xb0894a); addBox(0,-12,6,1,2.4,0x8b93a0);
+addBox(-12,0,1.5,6,2.0,0x77808c); addBox(12,-1,1.5,6,2.0,0x77808c);
+addBox(4,12,1.6,1.6,1.6,0xa08050); addBox(-4,12,1.6,1.6,1.6,0xa08050);
+
+/* ============ player state (from A) ============ */
+const player={x:0,z:20,y:0,vx:0,vz:0,vy:0,grounded:true,hp:PLAYER_HP};
+let YAW=0,PITCH=0;
+let keys={};
+let jumpQueued=false; // Space edge-triggered, no bunny-hop-hold
+addEventListener('keydown',e=>{
+  if(e.code==='Space')e.preventDefault();
+  if(e.code==='Space'&&!e.repeat)jumpQueued=true; // edge trigger only
+  keys[e.code]=true;
+  if(e.code==='KeyR')startReload();
+  if(e.code==='KeyP'&&state==='playing')pauseGame();
+});
+addEventListener('keyup',e=>{keys[e.code]=false;});
+
+/* ============ gun viewmodel + muzzle (A+B) ============ */
+const gun=new THREE.Group();
+const gBody=new THREE.Mesh(new THREE.BoxGeometry(0.09,0.13,0.62),new THREE.MeshLambertMaterial({color:0x22262c}));
+const gBar=new THREE.Mesh(new THREE.CylinderGeometry(0.022,0.022,0.34,10),new THREE.MeshLambertMaterial({color:0x111417}));
+gBar.rotation.x=Math.PI/2; gBar.position.set(0,0.02,-0.45);
+const gSight=new THREE.Mesh(new THREE.BoxGeometry(0.02,0.06,0.02),new THREE.MeshLambertMaterial({color:0x111111}));
+gSight.position.set(0,0.1,-0.18);
+const gMag=new THREE.Mesh(new THREE.BoxGeometry(0.07,0.18,0.1),new THREE.MeshLambertMaterial({color:0x2c3138}));
+gMag.position.set(0,-0.13,-0.05); gMag.rotation.x=0.25;
+gun.add(gBody,gBar,gSight,gMag);
+gun.position.set(0.22,-0.2,-0.45);
+camera.add(gun);
+const muzzle=new THREE.Object3D(); muzzle.position.set(0,0.02,-0.65); gun.add(muzzle);
+const flashLight=new THREE.PointLight(0xffc66e,0,9); scene.add(flashLight);
+const flashMat=new THREE.MeshBasicMaterial({color:0xffd777,transparent:true,opacity:0,blending:THREE.AdditiveBlending,depthWrite:false});
+const flashMesh=new THREE.Mesh(new THREE.PlaneGeometry(0.34,0.34),flashMat);
+flashMesh.position.set(0.22,-0.16,-0.9); camera.add(flashMesh);
+let muzzleTimer=0;
+
+/* ============ game flow state (from C) ============ */
+let state='menu'; // menu | playing | paused | over
+let result=null;
+let enemies=[],projectiles=[],tracers=[],puffs=[];
+let yaw=YAW;
+let hp=PLAYER_HP,lastDamageT=-99,elapsed=0,timeLeft=TIME_LIMIT;
+let kills=0,score=0,shotsFired=0,hits=0,spawned=0,wave=1,spawnT=0;
+let enemyId=0;
+const clock=new THREE.Clock();
+
+/* ============ shooting state (from A) ============ */
+let mag=MAG,reloading=false,reloadT=0;
+let triggerHeld=false,adsHeld=false,adsOn=false,adsF=0;
+let fireCd=0,spreadBloom=0,recoilP=0,recoilY=0,cameraKick=0;
+// Critic-A fix: 0.25s sprint-out delay gating fire+ADS
+let sprintT=99; // time since sprint ended; gates fire+ADS until > SPRINT_OUT
+let sprinting=false,sprintEndT=-99;
+let nowT=0;
+
+/* ============ WebAudio synth (from B, all WebAudio synth) ============ */
+let AC=null;
+function ac(){if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();return AC;}
+function noiseBuf(dur){const a=ac(),b=a.createBuffer(1,Math.floor(a.sampleRate*dur),a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;return b;}
+function env(g,t0,a,peak,dec){g.gain.setValueAtTime(0.0001,t0);g.gain.linearRampToValueAtTime(peak,t0+a);g.gain.exponentialRampToValueAtTime(0.0001,t0+a+dec);}
+function sShot(){try{const a=ac(),t=a.currentTime;const n=a.createBufferSource();n.buffer=noiseBuf(0.18);const f=a.createBiquadFilter();f.type='lowpass';f.frequency.setValueAtTime(3200,t);f.frequency.exponentialRampToValueAtTime(300,t+0.15);const g=a.createGain();env(g,t,0.004,0.7,0.16);n.connect(f);f.connect(g);g.connect(a.destination);n.start(t);n.stop(t+0.2);const o=a.createOscillator();o.type='square';o.frequency.setValueAtTime(160,t);o.frequency.exponentialRampToValueAtTime(45,t+0.12);const g2=a.createGain();env(g2,t,0.002,0.35,0.12);o.connect(g2);g2.connect(a.destination);o.start(t);o.stop(t+0.14);}catch(e){}}
+function sEnemyShot(){try{const a=ac(),t=a.currentTime;const o=a.createOscillator();o.type='sawtooth';o.frequency.setValueAtTime(700,t);o.frequency.exponentialRampToValueAtTime(120,t+0.18);const g=a.createGain();env(g,t,0.003,0.22,0.18);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+0.2);}catch(e){}}
+function sHit(){try{const a=ac(),t=a.currentTime;const o=a.createOscillator();o.type='sine';o.frequency.setValueAtTime(1400,t);o.frequency.exponentialRampToValueAtTime(900,t+0.06);const g=a.createGain();env(g,t,0.001,0.4,0.07);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+0.09);}catch(e){}}
+function sKill(){try{const a=ac(),t=a.currentTime;[660,880,1320].forEach((fr,i)=>{const o=a.createOscillator();o.type='triangle';o.frequency.value=fr;const g=a.createGain();env(g,t+i*0.07,0.005,0.4,0.12);o.connect(g);g.connect(a.destination);o.start(t+i*0.07);o.stop(t+i*0.07+0.15);});}catch(e){}}
+function sHurt(){try{const a=ac(),t=a.currentTime;const n=a.createBufferSource();n.buffer=noiseBuf(0.25);const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=500;const g=a.createGain();env(g,t,0.005,0.8,0.25);n.connect(f);f.connect(g);g.connect(a.destination);n.start(t);}catch(e){}}
+function sHeartbeat(){try{const a=ac(),t=a.currentTime;[0,0.18].forEach(dt=>{const o=a.createOscillator();o.type='sine';o.frequency.setValueAtTime(65,t+dt);o.frequency.exponentialRampToValueAtTime(40,t+dt+0.12);const g=a.createGain();env(g,t+dt,0.005,0.9,0.14);o.connect(g);g.connect(a.destination);o.start(t+dt);o.stop(t+dt+0.16);});}catch(e){}}
+function sReload(){try{const a=ac(),t=a.currentTime;[300,420].forEach((fr,i)=>{const o=a.createOscillator();o.type='square';o.frequency.value=fr;const g=a.createGain();env(g,t+i*0.12,0.005,0.18,0.08);o.connect(g);g.connect(a.destination);o.start(t+i*0.12);o.stop(t+i*0.12+0.1);});}catch(e){}}
+
+/* ============ HUD refs ============ */
+const $=id=>document.getElementById(id);
+const hitmarkerEl=$('hitmarker'),vign=$('vignette'),lowhp=$('lowhp'),dirHit=$('dirHit');
+const hpBar=$('healthBar'),hpNum=$('hpNum'),feed=$('killfeed'),strip=$('compassStrip'),toast=$('toast');
+let hitTimer=null,shake=0;
+function showHitmarker(kill){
+  // white-X hitmarker pop + red-X larger kill confirm; transform-based pop
+  hitmarkerEl.classList.remove('show','kill','pop');void hitmarkerEl.offsetWidth;
+  if(kill)hitmarkerEl.classList.add('kill');
+  hitmarkerEl.classList.add('show','pop');clearTimeout(hitTimer);
+  hitTimer=setTimeout(()=>hitmarkerEl.classList.remove('show','kill'),kill?450:180);
+}
+function addKillfeed(text){ // killfeed max 5
+  const d=document.createElement('div');d.className='feedline';d.textContent=text;
+  feed.prepend(d);while(feed.children.length>5)feed.lastChild.remove();
