+
+let scene, camera, renderer, clock;
+let state = 'menu'; // menu | playing | paused | over
+let result = null;  // 'win' | 'lose-hp' | 'lose-timeout'
+let player, enemies = [], projectiles = [], tracers = [], crates = [];
+let keys = {};
+let yaw = 0, pitch = 0;
+let hp = PLAYER_HP, lastDamageT = -99, elapsed = 0, timeLeft = TIME_LIMIT;
+let kills = 0, score = 0, shots = 0, hits = 0, spawned = 0, wave = 1, spawnT = 0;
+let ammo = 30, MAG = 30, reloading = false;
+let enemyId = 0;
+
+const $ = id => document.getElementById(id);
+const startMenu=$('startMenu'), pauseMenu=$('pauseMenu'), endScreen=$('endScreen');
+
+init();
+function init(){
+  scene = new THREE.Scene();
+  scene.background = new THREE.Color(0x87a5c4);
+  scene.fog = new THREE.Fog(0x87a5c4, 30, 110);
+  camera = new THREE.PerspectiveCamera(75, innerWidth/innerHeight, 0.1, 300);
+  renderer = new THREE.WebGLRenderer({canvas:$('c'), antialias:true});
+  renderer.setSize(innerWidth, innerHeight);
+  clock = new THREE.Clock();
+  // lights
+  scene.add(new THREE.HemisphereLight(0xffffff, 0x334455, 0.9));
+  const sun = new THREE.DirectionalLight(0xffffff, 1.1); sun.position.set(20,35,10); scene.add(sun);
+  // procedural map: ground + walls + crates
+  const g = new THREE.Mesh(new THREE.PlaneGeometry(80,80), new THREE.MeshLambertMaterial({color:0x5b7a52}));
+  g.rotation.x = -Math.PI/2; scene.add(g);
+  const grid = new THREE.GridHelper(80, 40, 0x000000, 0x000000); grid.material.transparent=true; grid.material.opacity=0.12; scene.add(grid);
+  const wallMat = new THREE.MeshLambertMaterial({color:0x8a8f96});
+  function wall(x,z,w,d,h=3){ const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),wallMat); m.position.set(x,h/2,z); scene.add(m); return m; }
+  wall(0,-30,80,1,5); wall(0,30,80,1,5); wall(-30,0,1,60,5); wall(30,0,1,60,5);
+  wall(-10,-8,8,1); wall(10,8,8,1); wall(0,-2,1,10);
+  const crateMat = new THREE.MeshLambertMaterial({color:0x9a6b3f});
+  const crateMat2 = new THREE.MeshLambertMaterial({color:0x6b7f9a});
+  [[-14,-14],[14,-14],[-14,14],[14,14],[0,-18],[0,18],[-6,4],[6,-4]].forEach(([x,z],i)=>{
+    const m = new THREE.Mesh(new THREE.BoxGeometry(2,2,2), i%2?crateMat2:crateMat);
+    m.position.set(x,1,z); m.rotation.y = i*0.4; scene.add(m); crates.push(m);
+  });
+  // player rig
+  player = { pos: new THREE.Vector3(0,1.7,20), vel: new THREE.Vector3(), onGround:true };
+  // gun stub (viewmodel box)
+  const gun = new THREE.Mesh(new THREE.BoxGeometry(0.08,0.12,0.5), new THREE.MeshBasicMaterial({color:0x222222}));
+  gun.position.set(0.22,-0.18,-0.5); camera.add(gun); scene.add(camera);
+  // events
+  addEventListener('resize', ()=>{ camera.aspect=innerWidth/innerHeight; camera.updateProjectionMatrix(); renderer.setSize(innerWidth,innerHeight); });
+  addEventListener('keydown', e=>{ keys[e.code]=true; if(e.code==='KeyR') startReload(); if(e.code==='KeyP'&&state==='playing') pauseGame(); });
+  addEventListener('keyup', e=>{ keys[e.code]=false; });
+  document.addEventListener('mousemove', e=>{
+    if(state!=='playing'||document.pointerLockElement==null) return;
+    yaw -= e.movementX*0.0023; pitch -= e.movementY*0.0023;
+    pitch = Math.max(-1.45, Math.min(1.45, pitch));
+  });
+  document.addEventListener('mousedown', e=>{
+    if(state==='playing' && document.pointerLockElement!=null && e.button===0) shoot();
+  });
+  document.addEventListener('pointerlockchange', ()=>{
+    if(document.pointerLockElement==null && state==='playing') pauseGame();
+  });
+  $('startBtn').onclick = ()=>{ resetGame(); lock(); };
+  $('resumeBtn').onclick = ()=>{ lock(); };
+  $('restartBtn').onclick = ()=>{ resetGame(); lock(); };
+  $('restartBtn2').onclick = ()=>{ resetGame(); lock(); };
+  camera.position.copy(player.pos); camera.rotation.order='YXZ';
+  animate();
+}
+function lock(){ renderer.domElement.requestPointerLock?.(); }
+// lock promise resolves async; unpause on next frame once locked OR immediately if already locked.
+// Simpler: set playing immediately; pause handler only fires on lock-loss after playing.
+function startReload(){ if(reloading||ammo===MAG||state!=='playing')return; reloading=true; setTimeout(()=>{ammo=MAG;reloading=false;updateHUD();},1100); }
+function pauseGame(){ if(state!=='playing')return; state='paused'; pauseMenu.style.display='flex'; }
+function resumeIfLocked(){
+  if(state==='paused' && document.pointerLockElement!=null){ state='playing'; pauseMenu.style.display='none'; clock.getDelta(); }
+}
+setInterval(resumeIfLocked, 200);
+
+function resetGame(){
+  // full reset without page reload (restart requirement)
+  for(const e of enemies) scene.remove(e.group);
+  for(const p of projectiles) scene.remove(p.mesh);
+  for(const t of tracers) scene.remove(t.mesh);
+  enemies=[]; projectiles=[]; tracers=[];
+  hp=PLAYER_HP; lastDamageT=-99; elapsed=0; timeLeft=TIME_LIMIT;
+  kills=0; score=0; shots=0; hits=0; spawned=0; wave=1; spawnT=0;
+  ammo=MAG; reloading=false; yaw=0; pitch=0; result=null;
+  player.pos.set(0,1.7,20); player.vel.set(0,0,0);
+  endScreen.style.display='none'; pauseMenu.style.display='none'; startMenu.style.display='none';
+  $('feed').innerHTML='';
+  state='playing';
+  updateHUD();
+}
+function spawnEnemy(){
+  const melee = Math.random()<0.5;
+  const grp = new THREE.Group();
+  const bodyMat = new THREE.MeshLambertMaterial({color: melee?0xb03030:0x7a2fd0});
+  const body = new THREE.Mesh(new THREE.CapsuleGeometry ? new THREE.CapsuleGeometry(0.4,0.9,4,8) : new THREE.BoxGeometry(0.8,1.4,0.5), bodyMat);
+  body.position.y = 1.0; grp.add(body);
+  const head = new THREE.Mesh(new THREE.SphereGeometry(0.28,12,10), new THREE.MeshLambertMaterial({color:0xffd9b0}));
+  head.position.y = 2.0; grp.add(head);
+  const eye = new THREE.Mesh(new THREE.BoxGeometry(0.3,0.08,0.05), new THREE.MeshBasicMaterial({color:0xff0000}));
+  eye.position.set(0,2.0,-0.26); grp.add(eye);
+  // spawn on far edge
+  const a = Math.random()*Math.PI*2, r = 22+Math.random()*5;
+  grp.position.set(Math.cos(a)*r, 0, Math.sin(a)*r*0.8);
+  scene.add(grp);
+  const e = { id:++enemyId, group:grp, body, hp:ENEMY_HP, melee, meleeCd:0, rangedCd:1+Math.random()*1.5, speed: melee?4.2:3.0, bob:Math.random()*6 };
+  body.userData.enemy = e; head.userData.enemy = e;
+  enemies.push(e); spawned++;
+  wave = Math.floor(kills/3)+1;
+}
+function shoot(){
+  if(reloading) return;
+  if(ammo<=0){ startReload(); return; }
+  ammo--; shots++;
+  // raycast from camera center against enemy bodies+heads
+  const rc = new THREE.Raycaster();
+  rc.setFromCamera({x:0,y:0}, camera);
+  const targets=[]; for(const e of enemies) targets.push(...e.group.children);
+  const hitsArr = rc.intersectObjects(targets, false);
+  // tracer visual
+  const dir = new THREE.Vector3(); camera.getWorldDirection(dir);
+  addTracer(camera.position.clone().add(dir.clone().multiplyScalar(0.5)), camera.position.clone().add(dir.clone().multiplyScalar(30)));
+  if(hitsArr.length && hitsArr[0].distance<60){
+    const en = hitsArr[0].object.userData.enemy;
+    if(en){ hits++; damageEnemy(en, 34, hitsArr[0].point); }
+  }
+  flashHit(false);
+  updateHUD();
+  if(ammo===0) startReload();
+}
+function damageEnemy(e, dmg, point){
+  e.hp -= dmg; flashHit(true);
+  // spark
+  const s = new THREE.Mesh(new THREE.SphereGeometry(0.09,6,6), new THREE.MeshBasicMaterial({color:0xffff66}));
+  s.position.copy(point||e.group.position.clone().add(new THREE.Vector3(0,1.2,0))); scene.add(s);
+  setTimeout(()=>scene.remove(s),120);
+  if(e.hp<=0) killEnemy(e);
+}
+function killEnemy(e){
+  scene.remove(e.group);
+  enemies = enemies.filter(x=>x!==e);
+  kills++; score+=100;
+  feed(`☠ Hostile ${e.id} down (+100)`);
+  updateHUD();
+  if(kills>=KILLS_TO_WIN) endGame('win');
+}
+function damagePlayer(dmg, fromPos){
+  if(state!=='playing') return;
+  hp -= dmg; lastDamageT = elapsed;
+  const v=$('vignette'); v.style.boxShadow='inset 0 0 140px rgba(255,0,0,.85)';
+  setTimeout(()=>v.style.boxShadow='inset 0 0 120px rgba(255,0,0,0)',160);
+  updateHUD();
+  if(hp<=0){ hp=0; endGame('lose-hp'); }
+}
+function endGame(r){
+  if(state==='over') return;
+  state='over'; result=r;
+  document.exitPointerLock?.();
+  const acc = shots? Math.round(hits/shots*100):0;
+  const tUsed = Math.round(elapsed);
+  $('stKills').textContent=kills; $('stTime').textContent=tUsed+'s';
+  $('stShots').textContent=shots; $('stAcc').textContent=acc+'%'; $('stScore').textContent=score;
+  const title=$('endTitle'), sub=$('endSub');
+  if(r==='win'){ title.textContent='🏆 MISSION COMPLETE'; title.style.color='#5dff8a';
+    sub.textContent=`win — eliminated ${kills}/${KILLS_TO_WIN} hostiles with ${fmt(timeLeft)} to spare.`; }
+  else if(r==='lose-hp'){ title.textContent='☠ KIA — YOU DIED'; title.style.color='#ff6b6b';
+    sub.textContent=`lose — HP reached 0 after ${tUsed}s. Kills ${kills}/${KILLS_TO_WIN}.`; }
+  else { title.textContent='⌛ TIMEOUT — MISSION FAILED'; title.style.color='#ffd257';
+    sub.textContent=`lose — 120s timer expired with only ${kills}/${KILLS_TO_WIN} kills.`; }
+  endScreen.style.display='flex';
+}
+function fmt(s){ s=Math.max(0,Math.ceil(s)); return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`; }
+function feed(msg){ const d=document.createElement('div'); d.textContent=msg; $('feed').prepend(d); while($('feed').children.length>5)$('feed').lastChild.remove(); setTimeout(()=>d.remove(),4000); }
+function flashHit(k){ const h=$('hitmark'); h.style.opacity=k?1:0.35; h.style.color=k?'#ffd257':'#ffffff'; setTimeout(()=>h.style.opacity=0,120); }
+function addTracer(a,b){ const geo=new THREE.BufferGeometry().setFromPoints([a,b]); const m=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xfff2a0,transparent:true,opacity:0.9})); scene.add(m); tracers.push({mesh:m,life:0.08}); }
+function updateHUD(){
+  $('kills').textContent=kills; $('remain').textContent=(KILLS_TO_WIN-kills)+' remaining';
+  $('timer').textContent=fmt(timeLeft); $('wave').textContent=wave; $('score').textContent=score;
+  $('hpnum').textContent=Math.ceil(hp); $('hpfill').style.width=(hp/PLAYER_HP*100)+'%';
+  $('ammo').textContent=reloading?'RELOADING…':`${ammo} / ∞`;
+  $('timerPill').classList.toggle('warn', timeLeft<20);
+}
+
+function animate(){
+  requestAnimationFrame(animate);
+  const dt = Math.min(clock.getDelta(), 0.05);
+  if(state==='playing'){
+    elapsed += dt; timeLeft -= dt;
+    if(timeLeft<=0){ timeLeft=0; updateHUD(); endGame('lose-timeout'); }
+    // movement (WASD + sprint + jump + gravity)
+    const sp = (keys.ShiftLeft||keys.ShiftRight)?7:4.5;
+    const f = new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));
+    const r = new THREE.Vector3(-f.z,0,f.x);
+    const mv = new THREE.Vector3();
+    if(keys.KeyW)mv.add(f); if(keys.KeyS)mv.sub(f); if(keys.KeyD)mv.add(r); if(keys.KeyA)mv.sub(r);
+    if(mv.lengthSq()>0)mv.normalize().multiplyScalar(sp*dt);
+    player.vel.x=mv.x/dt*0.12+player.vel.x*0.88; player.vel.z=mv.z/dt*0.12+player.vel.z*0.88;
+    if(keys.Space&&player.onGround){player.vel.y=5;player.onGround=false;}
+    player.vel.y-=12*dt;
+    player.pos.add(new THREE.Vector3(player.vel.x*dt,player.vel.y*dt,player.vel.z*dt));
+    player.pos.x=Math.max(-28,Math.min(28,player.pos.x)); player.pos.z=Math.max(-28,Math.min(28,player.pos.z));
+    if(player.pos.y<=1.7){player.pos.y=1.7;player.vel.y=0;player.onGround=true;}
+    camera.position.copy(player.pos); camera.rotation.set(pitch,yaw,0);
+    // hp regen after 4s no-damage
+    if(elapsed-lastDamageT>4 && hp<PLAYER_HP && hp>0){ hp=Math.min(PLAYER_HP,hp+18*dt); }
+    // wave spawning
+    spawnT-=dt;
+    const alive=enemies.length;
+    if(spawnT<=0 && alive<MAX_ALIVE && kills< KILLS_TO_WIN){ spawnEnemy(); spawnT=1.6; updateHUD(); }
+    // enemy AI
+    for(const e of [...enemies]){
+      const gp=e.group.position;
+      const to=new THREE.Vector3(player.pos.x-gp.x,0,player.pos.z-gp.z);
+      const dist=to.length(); to.normalize();
+      if(dist>1.8){ gp.addScaledVector(to, e.speed*dt); }
+      e.group.lookAt(player.pos.x,0,player.pos.z);
+      e.bob+=dt*6; e.group.position.y=Math.abs(Math.sin(e.bob))*0.08;
+      e.meleeCd-=dt; e.rangedCd-=dt;
+      if(dist<2.3 && e.meleeCd<=0){ e.meleeCd=1.1; damagePlayer(9+Math.random()*6, gp); }
+      if(!e.melee && dist<26 && dist>4 && e.rangedCd<=0){
+        e.rangedCd=2.2+Math.random();
+        const m=new THREE.Mesh(new THREE.SphereGeometry(0.12,8,8),new THREE.MeshBasicMaterial({color:0xff44ff}));
+        m.position.copy(gp).add(new THREE.Vector3(0,1.6,0)); scene.add(m);
+        const d=new THREE.Vector3(player.pos.x-m.position.x,(player.pos.y-0.2)-m.position.y,player.pos.z-m.position.z).normalize();
+        projectiles.push({mesh:m,vel:d.multiplyScalar(12),life:3});
+      }
+    }
+    // projectiles
+    for(const p of [...projectiles]){
+      p.mesh.position.addScaledVector(p.vel,dt); p.life-=dt;
+      const d=p.mesh.position.distanceTo(player.pos);
+      if(d<0.9){ damagePlayer(7, p.mesh.position); scene.remove(p.mesh); projectiles=projectiles.filter(x=>x!==p); }
+      else if(p.life<=0||p.mesh.position.y<0){ scene.remove(p.mesh); projectiles=projectiles.filter(x=>x!==p); }
+    }
+    // tracers fade
+    for(const t of [...tracers]){ t.life-=dt; t.mesh.material.opacity=Math.max(0,t.life/0.08); if(t.life<=0){scene.remove(t.mesh);tracers=tracers.filter(x=>x!==t);} }
+    updateHUD();
+  }
+  renderer.render(scene,camera);
+}
+</script>
+</body>
+</html>

