 /* ============ collision ============ */
 function collide(px,pz){
   const R=0.45;
   for(const c of colliders){
     if(player.y>=(c.h-0.2))continue;
     const nx=Math.max(c.minX,Math.min(px,c.maxX));
     const nz=Math.max(c.minZ,Math.min(pz,c.maxZ));
     const dx=px-nx,dz=pz-nz,dd=dx*dx+dz*dz;
     if(dd<R*R){
       if(dd>1e-6){const l=Math.sqrt(dd),push=(R-l)/l;px+=dx*push;pz+=dz*push;}
       else{px+=R;}
     }
   }
   px=Math.max(-23,Math.min(23,px));pz=Math.max(-23,Math.min(23,pz));
   return [px,pz];
 }

 /* ============ FOV: 75→55 critically-damped ~150ms settle ============ */
 let fovCur=75,fovVel=0;
 function updateFov(dt,target){
   const k=600,c=2*Math.sqrt(k); // critical damping, ~150ms settle
   const acc=k*(target-fovCur)-c*fovVel;
   fovVel+=acc*dt;fovCur+=fovVel*dt;
   camera.fov=fovCur;camera.updateProjectionMatrix();
 }

 /* ============ per-frame update ============ */
 let lastBeat=0,fpsA=60,fpsT=0,fpsN=0,last=performance.now();
 function step(dt){
   nowT+=dt;
   // ADS blend (gated by sprint-out)
   adsOn=adsHeld&&!reloading&&canAct();
   adsF+=((adsOn?1:0)-adsF)*Math.min(1,dt*12);
   // sprint state + sprintT (Critic-A fix)
   const wantSprint=(keys['ShiftLeft']||keys['ShiftRight'])&&!adsOn;
   const moving=(keys['KeyW']||keys['KeyA']||keys['KeyS']||keys['KeyD']);
   sprinting=!!(wantSprint&&moving);
   if(sprinting){sprintEndT=nowT;sprintT=0;}
   else sprintT=nowT-sprintEndT;
   const speed=adsOn?3.2:(sprinting?7.2:4.8); // ADS move slow
   let f=0,s=0;
   if(keys['KeyW']||keys['ArrowUp'])f+=1;if(keys['KeyS']||keys['ArrowDown'])f-=1;
   if(keys['KeyD']||keys['ArrowRight'])s+=1;if(keys['KeyA']||keys['ArrowLeft'])s-=1;
   const l=Math.hypot(f,s)||1;f/=l;s/=l;
   const sin=Math.sin(YAW),cos=Math.cos(YAW);
   const wx=(-sin*f+cos*s)*speed,wz=(-cos*f-sin*s)*speed;
   const accel=player.grounded?14:4;
   player.vx+=(wx-player.vx)*Math.min(1,accel*dt);
   player.vz+=(wz-player.vz)*Math.min(1,accel*dt);
   const r=collide(player.x+player.vx*dt,player.z+player.vz*dt);
   player.x=r[0];player.z=r[1];
   // gravity / jump on ground + box tops (edge-triggered)
   let groundY=0,onBox=false;
   for(const c of colliders){
     if(player.x>c.minX-0.3&&player.x<c.maxX+0.3&&player.z>c.minZ-0.3&&player.z<c.maxZ+0.3){
       if(player.y>=c.h-0.6&&player.y<=c.h+0.4){groundY=Math.max(groundY,c.h);onBox=true;}
     }}
   player.vy-=22*dt;
   if(jumpQueued){if(player.grounded){player.vy=8;player.grounded=false;}jumpQueued=false;}
   player.y+=player.vy*dt;
   if(player.y<=groundY){player.y=groundY;player.vy=0;player.grounded=true;}
   else if(!onBox&&player.y>groundY+0.02){player.grounded=(player.y<=groundY+0.02);}
   // recoil recovery persistent-ish (slow)
   recoilP*=Math.pow(0.02,dt);recoilY*=Math.pow(0.02,dt);
   spreadBloom=Math.max(0,spreadBloom-dt*2.2);
   // firing 700rpm auto, gated by sprint-out
   fireCd-=dt;
   if(triggerHeld&&!reloading&&fireCd<=0&&canAct())fireBullet();
   if(reloading){reloadT-=dt;if(reloadT<=0){reloading=false;mag=MAG;$('reload').style.display='none';updateHUD();}}
   // waves (max 3 alive, spawn 1.6s)
   spawnT-=dt;
   if(spawnT<=0&&enemies.filter(e=>e.alive).length<MAX_ALIVE&&kills<KILLS_TO_WIN){spawnEnemy();spawnT=SPAWN_EVERY;updateHUD();}
   // enemy seek AI: approach + strafe + melee + ranged
   for(const e of [...enemies]){
     const gp=e.group.position;
     if(!e.alive){
       e.dying+=dt;const k=Math.min(1,e.dying/0.9);
       e.group.rotation.x=-k*Math.PI/2;gp.y=-k*0.25;
       for(const m of e.mats)m.opacity=1-k; // death fall+fade
       continue;
     }
     if(e.hitFlash>0){e.hitFlash-=dt*4;if(e.hitFlash<=0)e.bodyMat.emissive=new THREE.Color(0x000000);}
     const toX=player.x-gp.x,toZ=player.z-gp.z;
     const dist=Math.hypot(toX,toZ)||0.001;
     const nx=toX/dist,nz=toZ/dist;
     e.group.rotation.y=Math.atan2(nx,nz)+Math.PI;
     const keep=dist>9?1:(dist<5?-1:0);
     e.strafe=(e.strafe||0)+dt*0.8;
     const svx=Math.cos(e.strafe)*0.5,svz=Math.sin(e.strafe)*0.5;
     let mvx=nx*keep+svx,mvz=nz*keep+svz;
     const ml=Math.hypot(mvx,mvz)||1;mvx/=ml;mvz/=ml;
     if(keep!==0||true){
       const sp2=e.speed*dt*(keep!==0?1:0.4);
       const tx=gp.x+mvx*sp2,tz=gp.z+mvz*sp2;
       if(Math.hypot(tx,tz)<23){gp.x=tx;gp.z=tz;}
     }
     e.bob+=dt*6;gp.y=Math.abs(Math.sin(e.bob))*0.08;
     e.meleeCd-=dt;e.rangedCd-=dt;
     if(dist<2.3&&e.meleeCd<=0){e.meleeCd=1.1;hurtPlayer(9+Math.random()*6,gp);}
     if(!e.melee&&dist<26&&dist>4&&e.rangedCd<=0){
       e.rangedCd=2.2+Math.random();
       const m=new THREE.Mesh(new THREE.SphereGeometry(0.12,8,8),new THREE.MeshBasicMaterial({color:0xff44ff}));
       m.position.copy(gp).add(new THREE.Vector3(0,1.6,0));scene.add(m);
       const d=new THREE.Vector3(player.x-m.position.x,(player.y+EYE-0.2)-m.position.y,player.z-m.position.z).normalize();
       projectiles.push({mesh:m,vel:d.multiplyScalar(12),life:3});
       const from=gp.clone().add(new THREE.Vector3(0,1.35,0));
       spawnTracer(from,m.position.clone(),0xff7a6a);
       sEnemyShot();
     }
   }
   // projectiles
   for(const p of [...projectiles]){
     p.mesh.position.addScaledVector(p.vel,dt);p.life-=dt;
     const d=Math.hypot(p.mesh.position.x-player.x,(p.mesh.position.y-(player.y+EYE)),p.mesh.position.z-player.z);
     if(d<0.9){hurtPlayer(7,p.mesh.position);scene.remove(p.mesh);projectiles=projectiles.filter(x=>x!==p);}
     else if(p.life<=0||p.mesh.position.y<0){scene.remove(p.mesh);projectiles=projectiles.filter(x=>x!==p);}
   }
   // tracers fade + dispose
   for(let i=tracers.length-1;i>=0;i--){const m=tracers[i];m.userData.life-=dt;m.material.opacity=Math.max(0,m.userData.life/m.userData.max);if(m.userData.life<=0)removeTracer(i);}
   // puffs
   for(let i=puffs.length-1;i>=0;i--){const s=puffs[i];s.userData.life-=dt;s.position.addScaledVector(s.userData.vel,dt);s.userData.vel.y-=6*dt;if(s.userData.grow)s.scale.addScalar(dt*3);s.material.opacity=Math.max(0,s.userData.life/s.userData.max*0.8);if(s.userData.life<=0){scene.remove(s);s.geometry.dispose();s.material.dispose();puffs.splice(i,1);}}
   // muzzle decay
   if(muzzleTimer>0){muzzleTimer-=dt;if(muzzleTimer<=0){flashMat.opacity=0;flashLight.intensity=0;}}
   flashMesh.rotation.z=Math.random()*Math.PI;flashMesh.scale.setScalar(0.8+Math.random()*0.6);
   flashLight.intensity*=Math.pow(0.001,dt);
   // damage numbers rise (transform-based)
   for(const s of dmgPool){
     if(s.life>0){s.life-=dt/0.9;if(s.life<=0){s.el.style.display='none';}else{s.el.style.transform='translate('+s.x+'px,'+(s.y-(1-s.life)*70)+'px)';s.el.style.opacity=String(Math.max(0,s.life));}}
   }
   // low-HP pulse + heartbeat + regen
   const t=performance.now()/1000;
   if(player.hp<=30&&player.hp>0){
     const pulse=(Math.sin(t*6)+1)/2;lowhp.style.opacity=String(0.35+pulse*0.4);
     if(t-lastBeat>1.0){lastBeat=t;sHeartbeat();}
     hpBar.classList.add('low');
   }else lowhp.style.opacity='0';
   if(player.hp<PLAYER_HP&&player.hp>0&&elapsed-lastDamageT>4){player.hp=Math.min(PLAYER_HP,player.hp+10*dt);updateHealth();}
+  else updateRegenTag(); // FIXER-FLOW: keep +REGEN in sync when not regening
   // timer (frozen when paused/unlocked)
   elapsed+=dt;timeLeft-=dt;
   if(timeLeft<=0){timeLeft=0;updateHUD();endGame('lose-timeout');}
 }
 function frame(now){
   requestAnimationFrame(frame);
   let dt=(now-last)/1000;last=now;
   if(dt>0.1)dt=0.1;
   if(state==='playing'){
     const STEP=1/120;stepAcc+=dt;let n=0;
     while(stepAcc>=STEP&&n<8){step(STEP);stepAcc-=STEP;n++;}
     if(n===8)stepAcc=0;
   }
   // camera (+ shake)
   shake=Math.max(0,shake-(state==='playing'?dt*2.2:0));
   const t=performance.now()/1000;
   const shx=(Math.random()-0.5)*shake*0.12,shy=(Math.random()-0.5)*shake*0.12;
   cameraKick*=0.85;
   camera.rotation.y=YAW+recoilY;
   camera.rotation.x=PITCH+recoilP+cameraKick*0.05;
   camera.rotation.z=0;
   camera.position.set(player.x+shx,player.y+EYE+shy+Math.sin(t*2)*0.02,player.z);
   if(state==='playing')updateFov(Math.min(dt,0.05),adsOn?55:75);
   // gun pos hip->ADS
   const gx=0.22*(1-adsF),gy=-0.2*(1-adsF)-0.148*adsF;
   gun.position.set(gx,gy+cameraKick*0.4,-0.45);
+  // BUILDER-W WEAPON FX BEGIN (sway/bob/reload-dip offsets; viewmodel only)
+  if(typeof updateBuilderWFX==='function'&&state==='playing'){try{updateBuilderWFX(Math.min(dt,0.05));}catch(e){}}
+  // BUILDER-W WEAPON FX END
   gun.visible=!reloading||Math.floor(now/150)%2===0;
   if(state==='playing')updateCompass();
   updateCrosshair();updateFps(dt);
   renderer.render(scene,camera);
 }
 let stepAcc=0;
 function updateCrosshair(){
   const gap=Math.max(3,6+spreadBloom*10+Math.hypot(player.vx,player.vz)*1.2+(adsOn?-3:0));
   const len=8,op=adsOn?0.35:1;
   function bar(el,x,y,w,h){el.style.left=x+'px';el.style.top=y+'px';el.style.width=w+'px';el.style.height=h+'px';el.style.opacity=String(op);}
   bar($('cht'),-1,-gap-len,2,len);bar($('chb'),-1,gap,2,len);bar($('chl'),-gap-len,-1,len,2);bar($('chr'),gap,-1,len,2);
+  // FIXER-FLOW: crosshair dim + SPRINT… tag while sprint-out blocks fire (!canAct())
+  try{
+    const blocked=(state==='playing'&&!canAct());
+    $('cross').classList.toggle('dim',blocked);
+    $('sprintTag').style.display=blocked?'block':'none';
+  }catch(e){}
 }
 function updateFps(dt){
   fpsT+=dt;fpsN++;
